from pathlib import Path

# Restore established prompt geometry exactly.
p = Path('index.html')
s = p.read_text()
old = '.completion-control-body>.record-card{box-shadow:none}.expandable-prompt.expanded{height:auto;max-height:none}'
new = '.completion-control-body>.record-card{box-shadow:none}.expandable-prompt{height:280px;max-height:280px}.expandable-prompt.expanded{height:auto;max-height:none}'
if old in s:
    s = s.replace(old, new)
elif '.expandable-prompt{height:280px;max-height:280px}' not in s:
    raise SystemExit('Expected prompt geometry anchor not found')
p.write_text(s)

# Strengthen Stage 25 prompt without subject-specific branching.
p = Path('prompt-engine.js')
s = p.read_text()
marker = "25:'Complete only after every current product/delivery artifact, required representation, page/view, transformation, and packaged file has actually been inspected through the proper authority path and no mandatory representation unknown remains.'"
replacement = "25:'Complete only after every current product/delivery artifact, required representation, page/view, transformation, and packaged file has actually been inspected through the proper authority path and no mandatory representation unknown remains. For each artifact, OBSERVATIONS must be a JSON STRING containing requiredPageOrViewIds, inspectedPageOrViewIds, requiredPackagedFileIds, openedOrTestedPackagedFileIds, requiredTransformationIds, inspectedTransformationIds, and observation. Use empty arrays only when that class genuinely does not apply; the application compares required and inspected identity sets exactly.'"
if marker in s:
    s = s.replace(marker, replacement)
if "closed-loop-prompt-engine/47" in s:
    s = s.replace("closed-loop-prompt-engine/47", "closed-loop-prompt-engine/48")
p.write_text(s)

# Add deterministic Stage 25 coverage and derived application facts.
p = Path('workflow-engine.js')
s = p.read_text()
anchor = '\nconst applicationadjudicationGate=gate;\n'
helper = '''\nfunction representationInspectionCoverage(project){\n  ensureShape(project);\n  const scope=currentScope(project),productId=String(scope.productId||''),artifacts=recordsForCurrentScope(project,'artifacts').filter(a=>productId&&String(a.scope?.productId||'')===productId),inspections=recordsForCurrentScope(project,'representationInspections'),reasons=[],details=[];\n  const normalizeList=value=>[...new Set(safe(value).map(x=>String(x??'').trim()).filter(Boolean))].sort();\n  const sameSet=(a,b)=>hash.sha256Value(normalizeList(a))===hash.sha256Value(normalizeList(b));\n  let totalPagesOrViewsRequired=0,totalPagesOrViewsInspected=0,totalPackagedFilesRequired=0,totalPackagedFilesOpenedOrTested=0,totalTransformationsRequired=0,totalTransformationsInspected=0;\n  for(const artifact of artifacts){\n    const artifactId=recordId(artifact,'artifacts'),rows=inspections.filter(i=>String(recordValue(i,'ARTIFACT_ID')||i.relationships?.ARTIFACT_ID||'')===artifactId);\n    if(rows.length!==1){reasons.push(`Exactly one current aggregate representation inspection is required for ${artifactId}; found ${rows.length}.`);continue;}\n    const inspection=rows[0];let payload=null;try{payload=JSON.parse(String(recordValue(inspection,'OBSERVATIONS')||''));}catch{reasons.push(`${recordId(inspection,'representationInspections')}: OBSERVATIONS must be the contracted strict JSON coverage object.`);continue;}\n    if(!payload||typeof payload!=='object'||Array.isArray(payload)){reasons.push(`${recordId(inspection,'representationInspections')}: OBSERVATIONS coverage payload is not an object.`);continue;}\n    const requiredPageOrViewIds=normalizeList(payload.requiredPageOrViewIds),inspectedPageOrViewIds=normalizeList(payload.inspectedPageOrViewIds),requiredPackagedFileIds=normalizeList(payload.requiredPackagedFileIds),openedOrTestedPackagedFileIds=normalizeList(payload.openedOrTestedPackagedFileIds),requiredTransformationIds=normalizeList(payload.requiredTransformationIds),inspectedTransformationIds=normalizeList(payload.inspectedTransformationIds),observation=String(payload.observation||'').trim();\n    totalPagesOrViewsRequired+=requiredPageOrViewIds.length;totalPagesOrViewsInspected+=inspectedPageOrViewIds.length;totalPackagedFilesRequired+=requiredPackagedFileIds.length;totalPackagedFilesOpenedOrTested+=openedOrTestedPackagedFileIds.length;totalTransformationsRequired+=requiredTransformationIds.length;totalTransformationsInspected+=inspectedTransformationIds.length;\n    if(!sameSet(requiredPageOrViewIds,inspectedPageOrViewIds))reasons.push(`${artifactId}: required page/view identities do not exactly match inspected page/view identities.`);\n    if(!sameSet(requiredPackagedFileIds,openedOrTestedPackagedFileIds))reasons.push(`${artifactId}: required packaged-file identities do not exactly match opened/tested packaged-file identities.`);\n    if(!sameSet(requiredTransformationIds,inspectedTransformationIds))reasons.push(`${artifactId}: required transformation identities do not exactly match inspected transformation identities.`);\n    if(!observation)reasons.push(`${artifactId}: representation observation is empty.`);\n    details.push({artifactId,requiredPageOrViewIds,inspectedPageOrViewIds,requiredPackagedFileIds,openedOrTestedPackagedFileIds,requiredTransformationIds,inspectedTransformationIds,observation});\n  }\n  const inspectionArtifactIds=new Set(inspections.map(i=>String(recordValue(i,'ARTIFACT_ID')||i.relationships?.ARTIFACT_ID||''))),expectedArtifactIds=new Set(artifacts.map(a=>recordId(a,'artifacts')));\n  for(const id of inspectionArtifactIds)if(id&&!expectedArtifactIds.has(id))reasons.push(`Representation inspection references non-current product artifact ${id}.`);\n  return {complete:artifacts.length>0&&reasons.length===0,reasons,productId,totalDeliveryArtifacts:artifacts.length,totalPagesOrViewsRequired,totalPagesOrViewsInspected,totalPackagedFilesRequired,totalPackagedFilesOpenedOrTested,totalTransformationsRequired,totalTransformationsInspected,details};\n}\n'''
if 'function representationInspectionCoverage(project)' not in s:
    if anchor not in s: raise SystemExit('Workflow gate anchor not found')
    s = s.replace(anchor, helper + anchor)

gate_anchor = "  const stageCollection={22:'deterministicResults',23:'meaningResults',24:'adversarialResults',25:'representationInspections'}[stage];if(stageCollection)for(const r of recordsForCurrentScope(project,stageCollection)){const e=evaluateResultConsistency(stageCollection,r,testForResult(project,r),project);if(e.determination!=='SATISFIED')add(e.reasons.length?e.reasons:[stageCollection+' contains a non-satisfied effective result.']);}\n"
if "if(stage===25){const coverage=representationInspectionCoverage(project)" not in s:
    if gate_anchor not in s: raise SystemExit('Stage 25 adjudication anchor not found')
    s = s.replace(gate_anchor, gate_anchor + "  if(stage===25){const coverage=representationInspectionCoverage(project);if(!coverage.complete)add(coverage.reasons.length?coverage.reasons:['Stage 25 representation coverage is incomplete.']);}\n")

old = "case 27:Object.assign(derived,{TOTAL_MANDATORY_REQUIREMENTS:release.mandatoryRequirementCount,MANDATORY_REQUIREMENTS_WITH_AFFIRMATIVE_SUPPORTING_EVIDENCE:release.satisfied,MANDATORY_REQUIREMENTS_DEMONSTRABLY_VIOLATED:release.violated,MANDATORY_REQUIREMENTS_NOT_ESTABLISHED:release.undetermined,UNRESOLVED_CRITICAL_DEFECTS:release.criticalDefects,UNRESOLVED_MAJOR_DEFECTS:release.majorDefects,SELECTED_RELEASE_STATE:release.determination});break;case 28:"
new = "case 25:{const coverage=representationInspectionCoverage(project),baseline=recordsForCurrentScope(project,'baselines').at(-1),product=recordsForCurrentScope(project,'products').at(-1),defects=unresolvedMaterialDefects(project);Object.assign(derived,{PRODUCT_ID:recordId(product,'products')||project.job.CURRENT_PRODUCT_ID||'NONE',PRODUCT_VERSION:recordValue(product,'PRODUCT_VERSION')||'NONE',REPRESENTATION_REVIEW_VERSION:'REPRESENTATION-'+hash.sha256Value(coverage.details).slice(0,16).toUpperCase(),APPROVED_BASELINE_ID:recordId(baseline,'baselines')||project.job.CURRENT_BASELINE_ID||'NONE',DELIVERY_ARTIFACT_INVENTORY:coverage.details.map(x=>x.artifactId),TRANSFORMATION_CHAIN_RECORDS:coverage.totalTransformationsInspected,PAGE_OR_VIEW_INSPECTION_RECORDS:coverage.totalPagesOrViewsInspected,PACKAGE_INSPECTION_RECORDS:coverage.totalPackagedFilesOpenedOrTested,TOTAL_DELIVERY_ARTIFACTS:coverage.totalDeliveryArtifacts,TOTAL_PAGES_OR_VIEWS_REQUIRED:coverage.totalPagesOrViewsRequired,TOTAL_PAGES_OR_VIEWS_INSPECTED:coverage.totalPagesOrViewsInspected,TOTAL_PACKAGED_FILES_REQUIRED:coverage.totalPackagedFilesRequired,TOTAL_PACKAGED_FILES_OPENED_OR_TESTED:coverage.totalPackagedFilesOpenedOrTested,UNRESOLVED_CRITICAL_DEFECTS:defects.filter(r=>upper(recordValue(r,'SEVERITY'))==='CRITICAL').length,UNRESOLVED_MAJOR_DEFECTS:defects.filter(r=>upper(recordValue(r,'SEVERITY'))==='MAJOR').length,UNRESOLVED_REPRESENTATION_UNKNOWNS:coverage.reasons.length,FINAL_REPRESENTATION_DETERMINATION:coverage.complete?'SATISFIED':'UNDETERMINED'});break;}case 27:Object.assign(derived,{TOTAL_MANDATORY_REQUIREMENTS:release.mandatoryRequirementCount,MANDATORY_REQUIREMENTS_WITH_AFFIRMATIVE_SUPPORTING_EVIDENCE:release.satisfied,MANDATORY_REQUIREMENTS_DEMONSTRABLY_VIOLATED:release.violated,MANDATORY_REQUIREMENTS_NOT_ESTABLISHED:release.undetermined,UNRESOLVED_CRITICAL_DEFECTS:release.criticalDefects,UNRESOLVED_MAJOR_DEFECTS:release.majorDefects,SELECTED_RELEASE_STATE:release.determination});break;case 28:"
if 'case 25:{const coverage=representationInspectionCoverage(project)' not in s:
    if old not in s: raise SystemExit('deriveStageData anchor not found')
    s = s.replace(old, new)

export_anchor='evaluateIntakeAccounting,obligationManifest,evaluateObligationAccounting,gate,deriveStageData,recalculate'
if 'representationInspectionCoverage' not in s[s.rfind('globalThis.closedLoopWorkflowEngine'):]:
    if export_anchor not in s: raise SystemExit('Workflow export anchor not found')
    s=s.replace(export_anchor,'evaluateIntakeAccounting,obligationManifest,evaluateObligationAccounting,representationInspectionCoverage,gate,deriveStageData,recalculate')
p.write_text(s)
